// D:\PythonProject3\src\components\Match.jsx

import React, { useState, useEffect } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

export default function Match({ userEmail }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);

  const ALLOWED_FEES = [13, 23, 50];

  useEffect(() => {
    if (game?.id) {
      const socket = new SockJS("http://localhost:8080/ludo-ws");
      const client = new Client({
        webSocketFactory: () => socket,
        onConnect: () => {
          client.subscribe(`/topic/match/${game.id}`, (message) => {
            const gameSession = JSON.parse(message.body);
            setGame(gameSession);
            setStatus("🎮 Game started! Good luck!");
          });
        },
        onStompError: (frame) => {
          console.error("STOMP error:", frame);
          setStatus("❌ Connection error.");
        },
      });

      client.activate();

      return () => {
        client.deactivate();
      };
    }
  }, [game?.id]);

  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(Number(entryFee))) {
      setStatus("❌ Invalid entry fee. Choose 13, 23, or 50.");
      return;
    }

    try {
      setStatus("🔍 Searching for opponent...");

      const response = await axios.post("http://localhost:8080/api/match/start", {
        entryFee,
        email: userEmail,
      });

      const data = response.data;

      if (data.gameId) {
        setStatus("🎉 Match found! Waiting for game to start...");
        setGame({ id: data.gameId });
        setPlayerId(data.playerId);
      } else {
        setStatus("⌛ Waiting for another player to join...");
      }
    } catch (err) {
      console.error(err);
      setStatus("⚠️ " + (err.response?.data?.message || "Server error"));
    }
  };

  return (
    <div className="max-w-md mx-auto mt-10 p-6 bg-gradient-to-br from-white to-gray-50 shadow-xl rounded-2xl border border-gray-200">
      <h2 className="text-2xl font-bold text-center text-blue-700 mb-4">
        🕹️ Start a Ludo Match
      </h2>

      <div className="mb-4">
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Select Entry Fee
        </label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-md shadow-md transition duration-200"
      >
        🔍 Find Opponent
      </button>

      {status && (
        <div className="mt-5 text-center text-gray-700 text-sm">
          <strong>Status:</strong> {status}
        </div>
      )}

      {game && game.id && (
        <div className="mt-6 p-4 text-center border border-green-300 bg-green-50 rounded-md">
          <p className="text-green-700 font-semibold">✅ Game ID: {game.id}</p>
          <p className="text-green-600">👤 You are Player {playerId}</p>
        </div>
      )}
    </div>
  );
}
